import{_ as o,a as r,b as a}from"./chunks/74e9204bb21c98affabb.ukS9sNxK.js";import{_ as n,C as s,o as i,c as l,j as e,a as c,E as g,a5 as h}from"./chunks/framework.DNkHA0lr.js";const A=JSON.parse('{"title":"如何成为你人生的主角","description":"","frontmatter":{"title":"如何成为你人生的主角","originalTitle":"How To Become The Main Character Of Your Life","date":"2025-06-02","originalUrl":"https://thedankoe.com/letters/how-to-become-the-main-character-of-your-life/","minutes":15,"sourceHash":"486c67f98239fb17b6bc0d22c6a1ca0805a53d506d050159171ff6e1e8287dc7","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-become-the-main-character-of-your-life/"}]]},"headers":[],"relativePath":"letters/how-to-become-the-main-character-of-your-life.md","filePath":"letters/how-to-become-the-main-character-of-your-life.md"}'),m={name:"letters/how-to-become-the-main-character-of-your-life.md"};function d(u,p,f,b,_,k){const t=s("ArticleMeta");return i(),l("div",null,[p[0]||(p[0]=e("h1",{id:"如何成为你人生的主角",tabindex:"-1"},[c("如何成为你人生的主角 "),e("a",{class:"header-anchor",href:"#如何成为你人生的主角","aria-label":'Permalink to "如何成为你人生的主角"'},"​")],-1)),g(t),p[1]||(p[1]=h('<blockquote><p>拥有能动性,就是成为句子的主语,而非直接宾语。它是一种主动出击的倾向,而不是等着被别人摆布。</p><p>——德文·埃里克森(Devon Eriksen)</p></blockquote><p>我曾是个非常爱评判的孩子。</p><p>我总是想不明白,为什么每个人都被洗脑得那么彻底。</p><p>我在教会的朋友们,一旦被我问及他们信仰真实性的问题,似乎总会瑟缩一下,眼中闪过一丝明显的错乱,那代表着他们的大脑猛然弹回到父母硬塞给他们的教条里。</p><p>这个世界在我看来太机械化了。</p><p>醒来。按几次闹钟延迟键。刷手机直到快要迟到。煮咖啡。堵在车流里。为你不在乎的人做你不在乎的项目。对老板挤出假笑。跟同事假笑寒暄。再堵车。跟配偶争吵。看电视。昏睡过去。重复。</p><p>这让我感到恐惧。</p><p>无论我转向哪个方向,都有人在推着我走上一条看似过时的道路,而这条路最终会通向和推我的人一样的生活。</p><p>省钱！</p><p>好好准备考试！</p><p>找份高薪工作！</p><p>就像电子游戏里的NPC。</p><p>非玩家角色。可预测、预先设定脚本、被编程的角色,遵循狭窄而严格的行为模式,没有能动性。他们身处游戏之中,而主角才是那个真正在玩这个游戏、掌控自己命运的人。</p><p>我一直对那些人心怀嫉妒。</p><p>那些不在乎别人怎么想的人。那些可以随心而活、无怨无悔的人。那些最终活出了充实而有趣的人生冒险的人。他们拥有MCE——主角能量(main character energy)。</p><p>至少那是我年少、愚蠢、天真时的想法。</p><h2 id="为什么有这么多npc" tabindex="-1">为什么有这么多NPC? <a class="header-anchor" href="#为什么有这么多npc" aria-label="Permalink to &quot;为什么有这么多NPC?&quot;">​</a></h2><blockquote><p>一般来说,我们有两种意识。一种我称之为“聚光灯”,另一种是“泛光灯”。聚光灯就是我们所说的有意注意,我们从小就被训练成认为这是最有价值的感知形式。当课堂上老师说“注意听!”时,每个人都会盯着老师看。那就是聚光灯意识:一次专注于一件事。你集中注意力,即便你的注意力持续时间可能不长,你依然在使用你的聚光灯:一件事接一件事,一件事接一件事……</p><p>——阿伦·瓦茨(Alan Watts)</p></blockquote><p>把大部分人简化为纯粹的木偶,并不是答案。</p><p>每个人都拥有一个复杂的内心世界,别人大都对此毫无察觉,也永远无法完全理解,因为他们根本无法接触到那个世界。</p><p>把患有“主角综合症”的自恋者捧上神坛,同样无益。</p><p>这两种都是扭曲的心理理论,但它们背后都有一定的道理。</p><p>我们不想只是<em>以为</em>自己是主角,我们想要<em>真正成为</em>主角,因为任何差一点的状态,都是在辜负你自身的潜力。</p><p>这个世界的尊重,只留给那些拥有高能动性的人。企业家、运动员、思想家。那些开辟自己道路、克服逆境、创造出令人不禁惊叹的故事的人。</p><p>其余的人则被扫到地毯下面,尽管这听起来有点刺耳。我们把他们标记为平庸、普通,他们很少能创造出被社会认定为足够有价值、值得用关注、金钱以及其他一切我们视为成功象征的东西来奖励的成果。</p><p>但为什么呢?</p><p>为什么这么少的人能从群体中脱颖而出、挣脱出来?</p><p>为什么我们几乎把所有的精力都献给了别人的梦想,而不是自己的?</p><p>我认为这个问题有3个相互交织的答案:条件化、工业化,以及第一层级思维(first-tier thinking)。</p><p>我们出生的那一刻,我们的心智就像一台没有操作系统的电脑。我们是一团团可爱又哭闹的人类肉球,四处乱动,如果没有得到适当的指导或照顾,我们就会死掉。</p><p>一颗天生就准备学习的大脑,配上一位急于塑造它的家长,这种组合很快就会变得危险。如果父母的“程序”几乎是他们自己父母程序的复制品——也就是说,他们没有被教导过(或没有practice过)能动性——那么孩子就更有可能得到同样的结局。必须有一个主角出现,才能打破这种代际诅咒。</p><p>再加上一个建立在工业化基础上的社会——一个以培养有用的工人为目的的系统——你就得到了美国梦:<em>上学,找工作,65岁退休。</em></p><p>你以为这已经够糟了?</p><p>其实,过去几十年里,人类心理学已经被广泛地绘制成图谱。</p><p>很明显,我们的心智——也就是我们的价值观、信念以及世界观,它们在很大程度上影响着我们如何思考和做决定——会随着时间以可预测的阶段不断演化。这些阶段可以归类为第一层级意识(first-tier consciousness)和第二层级意识(second-tier consciousness)。</p><p><img src="'+o+'" alt=""></p><p><em>第一层级思考者的一个决定性特征是,他们无法同时容纳多种视角。他们的信念是对的,你的是错的,而你就是他们的敌人。</em></p><p>所以,如果你的父母相信学校、工作和退休(或者某种特定的宗教或平等主义信念体系)对你最好,他们就会想办法确保你也这么相信。当你不知道还有别的可能时,这几乎是无法避免的。</p><p>西方超过95%的人口都处于第一层级思维的中上部分,可归为3个阵营:</p><ul><li><strong>秩序型(Order)</strong>——重视规则、角色和纪律,常常由某个外部的、全能的统治者赋予(比如那些拿着圣经敲桌子的人)</li><li><strong>成就型(Achievement)</strong>——重视理性、科学、冒险精神和自力更生(比如自助类内容或攀爬企业阶梯)</li><li><strong>平等主义型(Egalitarianism)</strong>——重视相对主义与平等。没有任何真理或信念是绝对的或更优越的,除了“没有任何真理更优越”这一点本身——这形成了一种危险的自相矛盾(比如性别或身份政治)</li></ul><p>这个世界感觉像是在冲你大喊:要么膜拜你的神,要么努力工作,要么成为社会权利的活动家,而更糟的是,身处信息时代,无论你转向哪里,人们都在试图说服你,这3个宏大的目标比你自己的目标更重要。</p><p>如果这些正是父母、老师、权威人士以及那些能直接接触到你年轻、易受影响头脑的公众人物所秉持的主流价值观,那么写入你脑中的代码,看起来就跟NPC没什么区别。</p><p>照别人说的做。</p><p>服从权威。</p><p>跟随群体。</p><p>而你没有别的选择。</p><p>生存是你的底层设定。它是你做出每一个决定背后的运行原则。如果你不是在保护自己的身体,那你就是在保护自己的自我(ego),而当你的自我还停留在第一层级的发展阶段时,你很快就会发现自己在对别人大发脾气,指责他们的信念有多么错误。那些可能改变你人生的新机会,则变得越来越稀少。</p><p>而且,如果你不服从父母或老师的信念,你可能会被部落驱逐,所以你自然而然地倾向于服从。</p><p>这就是为什么这个世界感觉如此机械。</p><p>这也是为什么这个世界如此容易被AI颠覆,以及为什么人们坐在那里抱怨AI会抢走工作,而不是去考虑另一种可能性。</p><p>我们被训练成收窄自己的注意力。</p><p>用瓦茨的话说,这就是“聚光灯意识”。</p><p>当权威说话时,我们听命。当我们被分配任务时,我们去执行。如果我们不这样做,我们就会感到受威胁,而那种恐惧反应会让我们继续朝着一个原本从来就不属于自己的目标努力。有些人无法忍受这种状态,于是坠入抑郁和焦虑的深渊,无法逃脱,因为他们的“聚光灯”看向了任何地方,却唯独没有照到就摆在身边、本可以用来搭建梯子的工具上。</p><p>默认路径就是我们的命运。我们透过“我们应该实现的目标”这一滤镜去看待世界。而如果你理解心智的运作方式,你就会明白,我们感知到的信息,恰恰是那些有助于我们达成既定目标的信息。</p><p>我们所能看到的一切,只是我们的“程序”允许我们看到的部分。</p><p>大多数关于意义、充实感和真正成功的机会,都在你眼皮底下悄悄溜走——除非你选择反叛。</p><p>除非你拒绝一切曾被告知为真的东西,去探寻你自己究竟能做到什么。</p><h2 id="反抗默认路径" tabindex="-1">反抗默认路径 <a class="header-anchor" href="#反抗默认路径" aria-label="Permalink to &quot;反抗默认路径&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>失败才是默认状态。</p><p>这就是人生残酷的真相。</p><p>如果你不去开创一条属于自己的路,你就会被分配一条,而无论你按照社会标准衡量有多么成功,那份成功从来都不属于你。从来不是你的目标。从来不是你的信念。从来不是你的行动。你只是一个程序,在运行着去实现别人为你设定的目标。</p><p>你并不注定要被自己的编程所束缚。这就是身为人类最酷的地方。我们是唯一能够重写自身代码的超级计算机,而即便是这个比喻,也远远不足以解释人类意识的复杂性。</p><p>如果你想改变人生的方向,你需要3种要素。</p><ul><li><strong>觉察力(Awareness)</strong>——拓宽你的视野光圈、发现机会的能力。</li><li><strong>获取力(Access)</strong>——把握这些机会所需的资源。</li><li><strong>能动性(Agency)</strong>——无需他人许可,就能采取行动去把握这些机会的能力。</li></ul><p>这些就是你成为自己人生主角的方法。</p><p>很多人都察觉到了机会。大多数人也拥有可以利用这些机会的知识和资源。<em>但真正付诸行动的人却寥寥无几。</em></p><p>正因如此,你在生活中能培养的每一种特质,都取决于最后这个要素:能动性。</p><p>大多数人仍然相信,智力或书本知识在成功中起着最重要的作用,但事实与此相去甚远。</p><p><strong>高智商 + 高能动性</strong> = 建造火箭飞船,把人类送上火星。</p><p><strong>低智商 + 高能动性</strong> = 大学本科第三年退学创业,根本不在乎所谓的“优化”。</p><p><strong>高智商 + 低能动性</strong> = 一路读到博士,只为哭诉富人本不该存在。他们永远不会越出护栏一步。</p><p><strong>低智商 + 低能动性</strong> = 那种遵循别人计划、把自己扮成境遇受害者的普通人。</p><p>只要有足够的能动性,你的智力高低根本无关紧要。</p><p>好消息是,能动性是一种习惯,而习惯是可以训练出来的。</p><h3 id="觉察力-拓宽你的视野光圈" tabindex="-1">觉察力:拓宽你的视野光圈 <a class="header-anchor" href="#觉察力-拓宽你的视野光圈" aria-label="Permalink to &quot;觉察力:拓宽你的视野光圈&quot;">​</a></h3><blockquote><p>从最广泛的意义上说,一个人对理解的追求,本质上是一个搜索问题——在一个抽象的观念空间里进行搜索,这个空间过于庞大,根本无法穷尽地搜索完毕。</p><p>——大卫·多伊奇(David Deutsch)</p></blockquote><p>我希望你把成功想象成一张地图。</p><p>没有图例。没有道路。没有地形。它大部分是空白的。</p><p>因此,成功就像是大海捞针。地图上一个看不见的针尖。</p><p>这张地图上唯一能显现出来的,是<em>已知的部分</em>。就像一束聚光灯,只照亮了地图的那一部分。对大多数人来说,这片区域被童年经历、学校教育、宗教灌输和职业培训所填满。</p><p>你当前版本的“成功”,是那片被界定区域内地图上一个<em>可见</em>的针尖。</p><p>你已经知道你的人生<em>应该</em>是什么样子,而你也基本上接受了这一点。你很少去思考<em>人生本可以是什么样子</em>,即便你曾想过,那种“还有更多可能”的念头很快就会被对未知的恐惧所取代。</p><p>这种恐惧是合理的。你不知道成功那个看不见的图钉在哪里。你不知道哪个方向能带你到那里。但这恰恰暗示了问题所在：你这一生都被人指路，所以你自然会以为自己需要指引才能成功。</p><p>这与事实相差甚远。</p><p>那么，你要如何在草堆中找到那根针呢？</p><p>首先，你需要一个深刻的、内在的理由，去纵身跃入未知。你需要残酷地意识到一个事实：你不想过一种机械化、被预先设定好的生活，因为你能直接观察到，大众所过的生活并不是你想要的生活。</p><p>人们不会改变，直到他们厌倦了那种病态的生活。接下来至少一个月，你每天都要思考你的生活正走向何方。你需要终于对自己坦诚：你当下生活中的那种不适，是你不愿再容忍的东西——因为如果你不厌恶它，你就会容忍它。</p><p>一旦你尝到了你所处生活的味道，转变的下一步便是<strong>失调</strong>——你当下的生活与潜在的生活会陷入一场角力赛。正是这种角力，为你的心智接受<strong>洞见</strong>做好了准备。</p><p>对负面的觉察，就像把一支弹弓向着积极的方向拉满弓弦。</p><p>其次，你需要对非常规的进步方式有一个大致的理解。你不应遵循那些通向已知且平庸结果的常规规则或指令，无论表面上看起来多么安全。</p><p>如果你想要非常规的结果，你就要做出一个猜测。你依据这个猜测去行动。你几乎可以保证会失败。你把这次失败当作一个数据点，一个需要修正的误差。你再做一次猜测，但这次是基于更充分的信息，慢慢地，你把未知变成已知，只要有足够的坚持，你就能逐渐排除那些不管用的东西，直到发现那些管用的东西。</p><p>这就是你创造知识的方式。</p><p>这就是你生成更深层觉察的方式。</p><p>这就是你摆脱单一的、第一层视角，开始拓展自身复杂性的方式。你在地图上探索的领域越多——无论是商业模式、灵性实践，还是健身方案——你的性格潜能就越大。</p><p>但这只是一个抽象的概念，需要具体化才有用。</p><h3 id="获取途径-利用新技术" tabindex="-1">获取途径：利用新技术 <a class="header-anchor" href="#获取途径-利用新技术" aria-label="Permalink to &quot;获取途径：利用新技术&quot;">​</a></h3><p>如果你想到达地图上的一个新区域，你需要获得进入那里的途径。</p><p>你至少需要一个大致的想法，知道某种机会藏在未知之中，再加上一系列你可以采取的步骤，来到达那个区域。</p><p>在一款电子游戏中，你必须达到一定的经验等级，才能（1）注意到这个任务，（2）接受这个任务，踏入未知之地。</p><p>问题是，我们要如何找到自己的下一个任务，并开始为之行动？</p><p>以你对当下生活方式产生失调感为前提，你的心智会变成机会的磁石。机会的问题在于，大多数人仍以一种“前信息时代”的心智在思考。他们没有意识到，学历、身处地理位置、金钱已经不再是通往机会的障碍。</p><p>你可以在互联网上学到任何东西。</p><p>你可以在各自领域追随专家。</p><p>你可以精心策划一个充满高信号密度想法的社交动态流。</p><p>你可以把你知道的、你做的事情分享给全世界看。</p><p>你可以利用技术这个<strong>杠杆</strong>来创业、提升灵性、与任何人交流、改善思维方式，或改变你的健康与体能状况。</p><p>这些既是机会的潜在来源，<strong>也是</strong>你付诸行动所需的资源。</p><p>然而大多数人却把互联网当成一种毒品来用。</p><p>为什么？聚光灯式的意识。</p><p>但我们已经越过了那个阶段。你已经准备好迎接人生的下一章了。</p><p>这些步骤看似极其简单，却越来越难做到：跟随那些致力于<strong>变得有用</strong>的人，无情地筛选谁能进入你的心智，并让自己接触到那些你其实每天都在刷屏时错过的机会——因为至少现在，你会真正注意到它们了。</p><p>我无法告诉你该走哪条路。</p><p>因为如果我这么做了，你可能会出于恐惧而死死抓住那条路不放，再一次收窄你的心智，以逃避那个孕育着潜能的不确定性。</p><h3 id="能动性-一切问题皆可解决" tabindex="-1">能动性：一切问题皆可解决 <a class="header-anchor" href="#能动性-一切问题皆可解决" aria-label="Permalink to &quot;能动性：一切问题皆可解决&quot;">​</a></h3><p>在1960年代末，马丁·塞利格曼（Martin Seligman）进行了一项著名的实验，用以证明狗是如何学会“无助”的。</p><p>实验分为三组狗，共两个阶段。</p><p><strong>第一阶段：</strong></p><ul><li>第1组狗被套上挽具并遭受电击，但它们可以学会按压一个面板来停止电击。它们拥有控制权。</li><li>第2组狗同样被套上挽具，遭受同样的电击，但无法停止电击。</li><li>第3组狗被套上挽具，时长相同，但没有遭受电击。</li></ul><p><strong>第二阶段（一天后）：</strong></p><p>所有组的狗被分别单独放入一个“穿梭箱”——一个由低矮隔板分隔成两个空间的箱子。在狗所在的那一侧，电击来临之前会有一个警示信号。</p><p>狗想要逃脱，只需要跳过隔板到达安全的一侧即可。</p><ul><li>第1组狗一看到警示信号出现，就立刻跳到另一侧，成功躲过了每一次电击。</li><li>第2组狗中大约有三分之二，甚至根本没有尝试逃脱电击。它们常常趴下、呜咽，忍受电击。</li><li>第3组狗很快就学会了躲避电击。</li></ul><p>正如第2组狗所显示的那样——这可能有点牵强——我认为，由于我们所成长的环境，西方人口中有三分之二的人已经习得了“无助”。</p><p>“习得性无助”的核心观点是：对某种令人厌恶的事件，<strong>感知上</strong>缺乏控制感，会导致被动性以及对痛苦的忍受。即使第2组的狗<strong>能够</strong>逃脱，它们也不会尝试，因为它们<strong>相信</strong>那是不可能的。</p><p>这有助于我们厘清低能动性个体与高能动性个体之间的一个关键区别。</p><p>你可能对自己的智力、出生的地方、被灌输的关于上帝、金钱或平等的信念几乎无法掌控，但能动性正是那个能让你跳过隔板的关键要素。</p><p>能动性是一种习惯，而非一种特质。正如无助感可以被习得一样，能动性也同样可以被习得。</p><p>拥有能动性，就是选择一个对<strong>你</strong>而言重要的目标，决定哪些行动能推动你朝那个目标前进，然后——听起来虽然简单——去行动。</p><p>但并非任何目标都可以。</p><p>当我们审视<strong>心流</strong>心理学——即最佳体验心理学——就会发现，愉悦感存在于已知的边缘。不至于难到让你被焦虑淹没，但也不能简单到让你很快感到厌烦。</p><p>那正是你失去自我意识、与挑战融为一体的地方。</p><p><img src="'+a+'" alt=""></p><p>所以，目标有三种类型：容易的、困难的，以及不可能的。</p><p>容易的目标，凭你现有的技能和资源就已经可以实现。</p><p>不可能的目标，则是我们做不到的事情，或者是因为它超出了可能性的范畴（比如物理法则），或者是因为我们还没有完成那个能使“看似不可能”变为可能的困难目标。</p><p>困难的任务，是我们无法立刻做到的事情，但只要我们成长、习得技能、积累必要的资源，最终就能做到。它们是那种你会先失败，但只要你坚持并不断迭代，最终就能成功的任务。</p><p>能动性——以及美好生活本身——就是对困难的信念。</p><p>能动性是一种信念：一切问题皆可解决。</p><p>能动性就是做<strong>优质科学</strong>的过程。</p><p>而这解开了拼图的最后一块。我们已经拥有觉察力。我们已经能够获取资源。但我们缺少那种推动我们迈向未知的<strong>实验精神</strong>。</p><p>优质科学分为四个部分：</p><ul><li><strong>目标</strong>——你致力于一个重要目标，这个目标往往源自你生活中的某个问题（或你不想要的东西）。</li><li><strong>实验</strong>——你猜测什么行动能推动你朝那个目标前进，并在现实世界中付诸行动。</li><li><strong>体验</strong>——与世界互动会带来一种体验。“datum”（数据的单数形式）的原始含义就是<strong>直接的体验</strong>。数据可以是身体上的、心理上的，或是灵性上的。</li><li><strong>验证</strong>——你观察这些数据，判断这次实验是让你更接近目标，还是让你离目标更远。</li></ul><p>如果你的目标是在风暴中抵达灯塔，你就扬帆出海，被吹离航向，转向左边，看看自己身处何方，然后不断修正航向，直到抵达灯塔。</p><p>这就是你在未知中航行的方式。</p><p>这就是你培养“主角能量”的方式。</p><p>你在地图上放下一个图钉，然后自己<strong>创造</strong>出通往那里的方向。</p><p>这样做，你就巩固了一份可以传承给人类的宝贵贡献，同时通过分享自己的经历，为自己的生活带来更深层次的幸福。</p><p>我相信，你现在已经具备了——从字面意义上讲——实现人生中任何目标所需要的一切。</p><p>如果你仍然在寻找速成办法、技巧或捷径，我建议你反复重读这封信，直到你不再有这种渴望。</p><p>你要独自前行，而这是一个了不起的领悟。</p><p>一路平安。</p><p>——丹（Dan）</p><p>本周提示：</p><p>“60天打造盈利个人品牌”挑战将于6月16日启动。</p><p>如果追求属于你自己的事业或创意事业对你来说是一个重要目标，并且你希望获得能帮助你实现这一目标的教育资源，<a href="https://stan.store/thedankoe/p/mini-course-how-i-systemize-my-life-with-ai" target="_blank" rel="noreferrer">请考虑在开始日期之前报名。</a></p><p>每天你都会收到一节课程和一个可执行的步骤，只需30到60分钟即可完成。到最后，你将弄清楚商业中最困难的那部分：如何变现、如何获取流量，以及如何建立信任。</p><hr><p><a href="/en/letters/how-to-become-the-main-character-of-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',159))])}const T=n(m,[["render",d]]);export{A as __pageData,T as default};
